"an": {"pos":"noun","gloss":"bow","def":"ship's bow; the forward end of a spacecraft or vessel","en":["bow","ship bow","forepart"],"status":"proposed-extension","source":"User-selected Marain navigation vocabulary (2026-10-29)","derivation":"User-selected short lexical form; no attested derivation.","note":"Forward end of a vessel; not an archery bow or the act of bowing. User-selected replacement; not attested in Banks or surviving lessons.","former_proposal":"prenwetsE","replaces":"pawet"},
"bet": {"pos":"noun","gloss":"aft","def":"aft; the sternward direction or rear of a spacecraft or vessel","en":["aft","stern","ship stern"],"status":"proposed-extension","source":"User-selected Marain navigation vocabulary (2026-10-29)","derivation":"User-selected short lexical form; no attested derivation.","note":"Vessel-relative direction, not simply behind the observer. User-selected replacement; not attested in Banks or surviving lessons.","former_proposal":"prenwia","replaces":"pawi"},
"pakat": {"pos":"noun","gloss":"starboard","def":"starboard; the right-hand side of a vessel when facing its bow","en":["starboard","starboard side"],"status":"proposed-extension","source":"User-selected Marain navigation vocabulary (2026-10-29)","derivation":"User-selected short lexical form; no attested derivation.","note":"Nautical orientation, fixed relative to the vessel's bow. User-selected replacement; not attested in Banks or surviving lessons.","former_proposal":"prenkataH","replaces":"pakata"},
"fapren": {"pos":"noun","gloss":"train","def":"train; a guided-route or rail-bound transit vehicle","en":["train","rail train"],"status":"proposed-extension","source":"Marain dictionary extension (2026-10-29); frequent-use lexicalized shortening","derivation":"fa- (shortened fAyont, way/path) + pren (vehicle, as in guHetpren)","note":"Proposed rail/guided-way sense, including vehicle transit inside ships or Orbitals; the inherited land-vehicle component is an approximation. Lexicalized frequent-use contraction of the earlier provisional compound fAyontguHetpren; this does not establish a general Marain clipping rule.","former_proposal":"fAyontguHetpren"},
"SlA": {"pos":"noun","gloss":"elevator","def":"elevator; lift machine for vertical travel between levels","en":["elevator","lift","passenger lift"],"status":"proposed-extension","source":"Marain dictionary extension (2026-10-29); frequent-use lexicalized shortening","derivation":"S- (shortened Sin, above/up) + lA (machine)","note":"Passenger or cargo elevator sense; not every machine that moves vertically. Lexicalized frequent-use contraction of the earlier provisional compound SinshalA; this does not establish a general Marain clipping rule.","former_proposal":"SinshalA"},
"wemag": {"pos":"noun","gloss":"stairs","def":"stairs; a stepped route connecting different floor levels","en":["stairs","stairway","staircase","steps"],"status":"proposed-extension","source":"Marain dictionary extension (2026-10-29); frequent-use lexicalized shortening","derivation":"we- (shortened wek, hand/foot) + mag (floor/deck)","note":"Lexicalised as a sequence of foot treads; excludes ramps. The foot-specific meaning of wek is contextual rather than exclusive. Lexicalized frequent-use contraction of the earlier provisional compound wekmagfAyont; this does not establish a general Marain clipping rule.","former_proposal":"wekmagfAyont"},
